package com.bank.dr;

import java.util.*;
import java.util.logging.*;

public class DrAdvisorDemo {
    private static final Logger log = Logger.getLogger("DisasterRecovery");

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        DrAdvisor advisor = new DrAdvisor();

        List<Workload> workloads = List.of(
            new Workload("core-payment-ledger", new DrTargets(1, 5)),      // near-zero loss, minutes
            new Workload("customer-api",        new DrTargets(5, 30)),     // small loss, half hour
            new Workload("internal-report",     new DrTargets(1440, 240)));// a day loss, hours

        for (Workload w : workloads) {
            String strategy = advisor.recommend(w.targets());
            log.info(() -> w.name() + " (RPO " + w.targets().rpoMinutes()
                    + "m, RTO " + w.targets().rtoMinutes() + "m) -> " + strategy
                    + " [cost " + advisor.relativeCost(strategy) + "]");
        }
    }
}

// ─── Would be in DrAdvisor.java ───
class DrAdvisor {
    // Tighter RPO/RTO → faster, costlier strategy.
    String recommend(DrTargets t) {
        if (t.rpoMinutes() <= 1 && t.rtoMinutes() <= 5) {
            return "Multi-Site Active-Active (near-zero RPO/RTO, full copy in another region)";
        }
        if (t.rtoMinutes() <= 30) {
            return "Warm Standby (scaled-down copy always running, scale up on failover)";
        }
        if (t.rtoMinutes() <= 120) {
            return "Pilot Light (minimal core running, scale up the rest on disaster)";
        }
        return "Backup & Restore (rebuild from backups, recover in hours)";
    }

    String relativeCost(String strategy) {
        if (strategy.startsWith("Multi-Site")) return "$$$$ highest";
        if (strategy.startsWith("Warm"))       return "$$$ high";
        if (strategy.startsWith("Pilot"))      return "$$ medium";
        return "$ lowest";
    }
}

// ─── Would be in DrTargets.java ───
class DrTargets {
    private final int rpoMinutes; // how much data loss is tolerable
    private final int rtoMinutes; // how long down is tolerable
    DrTargets(int rpoMinutes, int rtoMinutes) { this.rpoMinutes = rpoMinutes; this.rtoMinutes = rtoMinutes; }
    int rpoMinutes() { return rpoMinutes; }
    int rtoMinutes() { return rtoMinutes; }
}

// ─── Would be in Workload.java ───
class Workload {
    private final String name;
    private final DrTargets targets;
    Workload(String name, DrTargets targets) { this.name = name; this.targets = targets; }
    String name() { return name; }
    DrTargets targets() { return targets; }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                r.getMillis(), r.getLevel(), r.getMessage());
    }
}
